def transform(grid):
    h, w = len(grid), len(grid[0])

    sep_rows = [r for r in range(h) if len(set(grid[r])) == 1]
    sep_cols = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1]

    def spans(size, separators):
        groups = []
        start = 0
        for x in separators:
            if start < x:
                groups.append((start, x))
            start = x + 1
        if start < size:
            groups.append((start, size))
        return groups

    row_groups = spans(h, sep_rows)
    col_groups = spans(w, sep_cols)

    from collections import Counter
    colors = Counter(
        grid[r][c]
        for r in range(h) if r not in sep_rows
        for c in range(w) if c not in sep_cols
    )
    background = colors.most_common(1)[0][0]

    counts = []
    for r0, r1 in row_groups:
        row_counts = []
        for c0, c1 in col_groups:
            row_counts.append(sum(
                grid[r][c] != background
                for r in range(r0, r1)
                for c in range(c0, c1)
            ))
        counts.append(row_counts)

    maximum = max(max(row) for row in counts)
    return [[1 if counts[r][c] == maximum else background
             for c in range(len(col_groups))]
            for r in range(len(row_groups))]
